def infix_to_postfix_helper(expr):
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
    stack  = []
    output = []

    for token in expr:
        if token.isalnum():
            output.append(token)
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            stack.pop()
        else:
            while (stack and
                   stack[-1] != '(' and
                   precedence.get(stack[-1], 0) >= precedence[token]):
                output.append(stack.pop())
            stack.append(token)

    while stack:
        output.append(stack.pop())

    return output


def infix_to_prefix(expr):
    # Step 1: Reverse
    rev = expr[::-1]

    # Step 2: Swap brackets
    swapped = []
    for token in rev:
        if token == '(':
            swapped.append(')')
        elif token == ')':
            swapped.append('(')
        else:
            swapped.append(token)

    # Step 3: Apply postfix conversion
    postfix = infix_to_postfix_helper(swapped)

    # Step 4: Reverse result
    prefix = postfix[::-1]

    return ' '.join(prefix)


